//! Post-boot duties of a primary: idempotently ensure the replication role
//! exists with the configured password. Runs after postgres accepts
//! connections; safe to repeat on every startup.

use std::time::Duration;

use crate::config::Config;
use crate::status;

/// A password we are willing to interpolate into DDL. Both passwords are
/// generated by the server from this alphabet; '$' in particular must stay out
/// so the $pglord$ dollar-quoting below cannot be closed from inside a value.
pub fn is_safe_password(password: &str) -> bool {
    !password.is_empty()
        && password
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

/// `reset_superuser` is set for clusters created by a restore: the restored
/// data carries the *source* cluster's roles, so this cluster's own generated
/// superuser password would not open it. The local socket uses peer auth, so
/// we can still get in to fix it.
pub async fn ensure_roles(cfg: &Config, reset_superuser: bool) {
    if cfg.repl_password.is_empty() {
        tracing::warn!("no replication password configured; skipping role setup (trust mode)");
        return;
    }
    // Wait for postgres to accept connections (bounded). A restored instance
    // replays WAL first, so this can legitimately take a while.
    for _ in 0..60u32 {
        if status::query_status(cfg).await.ready {
            break;
        }
        tokio::time::sleep(Duration::from_secs(2)).await;
    }
    match try_ensure(cfg, reset_superuser).await {
        Ok(()) => tracing::info!(role = %cfg.repl_user, reset_superuser, "roles ensured"),
        Err(err) => tracing::error!(%err, "failed to ensure roles"),
    }
}

/// Run the cluster's init scripts, once, after the roles exist.
///
/// Ordered after role setup on purpose: a script that grants privileges to the
/// replication role would otherwise fail on a role that does not exist yet.
pub async fn ensure_initialised(cfg: &Config, spec: &pglord_core::spec::ClusterSpec) {
    if !crate::initdb::init_pending(&cfg.pgdata) {
        return;
    }
    for _ in 0..60u32 {
        if status::query_status(cfg).await.ready {
            break;
        }
        tokio::time::sleep(Duration::from_secs(2)).await;
    }
    match crate::initdb::run_scripts(cfg, spec).await {
        Ok(()) => {
            // Marked only on success, so a failed script is retried when the
            // pod restarts rather than silently skipped forever.
            if let Err(err) = crate::initdb::mark_initialised(&cfg.pgdata) {
                tracing::error!(%err, "init scripts ran but the marker could not be written");
            } else if !spec.init.is_empty() {
                tracing::info!("init scripts complete");
            }
        }
        Err(err) => tracing::error!(%err, "init scripts failed; will retry on restart"),
    }
}

/// Local superuser connection over the socket (peer auth — works even when
/// the env password is stale, which is the whole point during rotation).
async fn connect_local(
    cfg: &Config,
) -> anyhow::Result<(
    tokio_postgres::Client,
    tokio::task::JoinHandle<Result<(), tokio_postgres::Error>>,
)> {
    let conn_str = format!(
        "host={} port={} user={} password={} dbname=postgres connect_timeout=5",
        cfg.socket_dir.display(),
        cfg.port,
        cfg.superuser,
        cfg.superuser_password,
    );
    let (client, connection) = tokio_postgres::connect(&conn_str, tokio_postgres::NoTls).await?;
    Ok((client, tokio::spawn(connection)))
}

/// CREATE or ALTER the replication role with the given password.
///
/// Role name and password are interpolated into DDL (Postgres cannot bind
/// them as parameters); the charset invariants are enforced explicitly so a
/// misconfigured value cannot smuggle SQL, and the password is dollar-quoted
/// with a tag its alphabet cannot contain.
async fn ensure_repl_role(
    client: &tokio_postgres::Client,
    repl_user: &str,
    repl_password: &str,
) -> anyhow::Result<()> {
    if repl_user.is_empty()
        || !repl_user
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_')
    {
        anyhow::bail!("repl_user must be non-empty alphanumeric/underscore");
    }
    if !is_safe_password(repl_password) {
        anyhow::bail!("repl_password may only contain [A-Za-z0-9_-]");
    }
    let exists: bool = client
        .query_one(
            "SELECT EXISTS(SELECT 1 FROM pg_roles WHERE rolname = $1)",
            &[&repl_user],
        )
        .await?
        .get(0);
    let verb = if exists { "ALTER" } else { "CREATE" };
    client
        .batch_execute(&format!(
            "{verb} ROLE \"{repl_user}\" WITH REPLICATION LOGIN PASSWORD $pglord${repl_password}$pglord$"
        ))
        .await?;
    Ok(())
}

/// ALTER the superuser's password. Same interpolation invariants as above.
async fn alter_superuser(
    client: &tokio_postgres::Client,
    superuser: &str,
    superuser_password: &str,
) -> anyhow::Result<()> {
    if !is_safe_password(superuser_password) {
        anyhow::bail!("superuser_password may only contain [A-Za-z0-9_-]");
    }
    if !superuser
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '_')
    {
        anyhow::bail!("superuser must be alphanumeric/underscore");
    }
    client
        .batch_execute(&format!(
            "ALTER ROLE \"{superuser}\" WITH PASSWORD $pglord${superuser_password}$pglord$"
        ))
        .await?;
    Ok(())
}

/// Apply NEW passwords to both roles in one connection. Used by the rotation
/// endpoint; postboot's own startup path keeps applying the env passwords.
pub async fn apply_passwords(
    cfg: &Config,
    superuser_password: &str,
    repl_password: &str,
) -> anyhow::Result<()> {
    let (client, conn_task) = connect_local(cfg).await?;
    ensure_repl_role(&client, &cfg.repl_user, repl_password).await?;
    alter_superuser(&client, &cfg.superuser, superuser_password).await?;
    drop(client);
    conn_task.abort();
    Ok(())
}

/// Idempotently ensure everything PgBouncer's `auth_query` needs, in the
/// `postgres` database (`connect_local` targets it — matching the pooler's
/// `auth_dbname = postgres`): the `pglord_pooler` role with the given
/// password, the `pglord` schema, and a SECURITY DEFINER lookup over
/// `pg_shadow` that only that role may execute.
pub async fn ensure_pooler(cfg: &Config, password: &str) -> anyhow::Result<()> {
    if !is_safe_password(password) {
        anyhow::bail!("pooler password may only contain [A-Za-z0-9_-]");
    }
    let (client, conn_task) = connect_local(cfg).await?;
    let exists: bool = client
        .query_one(
            "SELECT EXISTS(SELECT 1 FROM pg_roles WHERE rolname = 'pglord_pooler')",
            &[],
        )
        .await?
        .get(0);
    let verb = if exists { "ALTER" } else { "CREATE" };
    client
        .batch_execute(&format!(
            "{verb} ROLE \"pglord_pooler\" WITH LOGIN PASSWORD $pglord${password}$pglord$"
        ))
        .await?;
    client
        .batch_execute(
            "CREATE SCHEMA IF NOT EXISTS pglord;\n\
             REVOKE ALL ON SCHEMA pglord FROM PUBLIC;\n\
             GRANT USAGE ON SCHEMA pglord TO \"pglord_pooler\";\n\
             CREATE OR REPLACE FUNCTION pglord.pooler_lookup(uname text)\n\
             RETURNS TABLE (usename name, passwd text)\n\
             LANGUAGE sql SECURITY DEFINER AS\n\
             $fn$ SELECT usename, passwd FROM pg_shadow WHERE usename = uname $fn$;\n\
             REVOKE ALL ON FUNCTION pglord.pooler_lookup(text) FROM PUBLIC;\n\
             GRANT EXECUTE ON FUNCTION pglord.pooler_lookup(text) TO \"pglord_pooler\";",
        )
        .await?;
    drop(client);
    conn_task.abort();
    Ok(())
}

async fn try_ensure(cfg: &Config, reset_superuser: bool) -> anyhow::Result<()> {
    let (client, conn_task) = connect_local(cfg).await?;
    ensure_repl_role(&client, &cfg.repl_user, &cfg.repl_password).await?;
    if reset_superuser {
        alter_superuser(&client, &cfg.superuser, &cfg.superuser_password).await?;
        tracing::info!(role = %cfg.superuser, "superuser password reset to this cluster's own");
    }
    drop(client);
    conn_task.abort();
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dollar_signs_are_rejected_in_passwords() {
        // The DDL dollar-quotes the password with a $pglord$ tag; a value
        // containing '$' could close that tag and inject SQL.
        assert!(is_safe_password("aB3-x_9"));
        assert!(!is_safe_password("has$pglord$end"));
        assert!(!is_safe_password("quote'ish"));
        assert!(!is_safe_password(""));
    }
}
